// Pure semantic verification after the caller has independently read and hashed
// every archive file. Does not infer an effective address or event outcome.
import {createHash} from 'node:crypto';import {projectDelivery} from '../../reporting-api-mirror.mjs';
const verified=Symbol('verified source snapshot');
export const isVerifiedSourceProof=x=>x?.[verified]===true;
const sha=x=>createHash('sha256').update(Buffer.isBuffer(x)?x:JSON.stringify(x)).digest('hex');
export function verifyArchivedCapture({day,expectedSnapshotHash,expectedObservedAt,snapshotBytes,manifest,context,checkpoint,pages}){
 if(!Buffer.isBuffer(snapshotBytes)||!Array.isArray(pages))throw Error('Invalid source capture');const s=JSON.parse(snapshotBytes),r=s.receipt;if(s.kind!=='matter-api-mirror-v1'||s.day!==day||s.snapshotHash!==expectedSnapshotHash||s.snapshotHash!==sha({day:s.day,rows:s.rows,locations:s.locations})||s.deliveryObservedAt!==expectedObservedAt||manifest?.sha256!==sha(snapshotBytes)||manifest.bytes!==snapshotBytes.length||manifest.day!==day||context?.day!==day||manifest.runId!==context.runId||!r?.snapshotComplete||r.rowCount!==s.rows.length||r.uniqueCount!==s.rows.length||new Set(s.rows.map(x=>x.id)).size!==s.rows.length||pages.length!==r.pageCount||checkpoint?.snapshotComplete!==true||checkpoint.pageCount!==pages.length||!Array.isArray(checkpoint.pages)||checkpoint.pages.length!==pages.length)throw Error('Invalid archived source binding');const raw=[],times=[];for(let i=0;i<pages.length;i++){const p=pages[i],b=p?.body;if(!b||p.sha256!==sha(b)||checkpoint.pages[i].sha256!==p.sha256||checkpoint.pages[i].observedAt!==b.observedAt||b.page!==i+1||b.pagination?.hasMore!==(i<pages.length-1)||!Array.isArray(b.rows))throw Error('Invalid archived source page');times.push(b.observedAt);raw.push(...b.rows)}if(raw.length!==s.rows.length||new Set(raw.map(x=>x.id)).size!==raw.length||r.sourceObservedAt?.from!==times[0]||r.sourceObservedAt?.to!==times.at(-1)||s.deliveryObservedAt!==times.at(-1))throw Error('Invalid archived source population');const projected=raw.map(x=>projectDelivery(x,day)).sort((a,b)=>a.id.localeCompare(b.id));for(let j=0;j<projected.length;j++){const saved=s.rows[j],row=projected[j];if(!Object.hasOwn(saved,'trackerVisit')&&row.trackerVisit===null)delete row.trackerVisit;if(row.proof&&saved.proof)for(const k of ['photoCapturedAt','receivedAt','photoSource','location'])if(!Object.hasOwn(saved.proof,k)&&row.proof[k]===null)delete row.proof[k]}if(sha(projected)!==sha(s.rows))throw Error('Archived source projection mismatch');return Object.freeze({day,snapshotHash:s.snapshotHash,observedAt:s.deliveryObservedAt,rows:s.rows.length,pages:pages.length,[verified]:true});
}
export function verifyCloudSourceCapture({day,expectedSnapshotHash,expectedObservedAt,capture,pages}){const s=capture?.snapshot,r=s?.receipt,meta=capture?.pages;if(capture?.day!==day||!/^stream-[0-9]+$/.test(capture?.runId||'')||s?.day!==day||s.snapshotHash!==expectedSnapshotHash||s.snapshotHash!==sha({day:s.day,rows:s.rows,locations:s.locations})||s.deliveryObservedAt!==expectedObservedAt||!r?.snapshotComplete||r.rowCount!==s.rows.length||r.uniqueCount!==s.rows.length||!Array.isArray(meta)||!Array.isArray(pages)||meta.length!==r.pageCount||pages.length!==meta.length)throw Error('Invalid cloud source capture');const raw=[],times=[];for(let i=0;i<pages.length;i++){const x=pages[i],m=meta[i],b=x?.body;if(!b||m.page!==i+1||m.ref?.sha256!==m.sha256||m.ref?.key!==m.sha256+'.gz'||x.sha256!==m.sha256||!Buffer.isBuffer(x.bytes)||sha(x.bytes)!==m.sha256||JSON.stringify(JSON.parse(x.bytes))!==JSON.stringify(b)||!Number.isFinite(Date.parse(m.observedAt))||i>0&&Date.parse(m.observedAt)<Date.parse(times.at(-1))||b.pagination?.page!==i+1||b.pagination?.total!==s.rows.length||b.pagination?.pages!==pages.length||!Array.isArray(b.data))throw Error('Invalid cloud source page');times.push(m.observedAt);raw.push(...b.data)}if(raw.length!==s.rows.length||new Set(raw.map(x=>x.id)).size!==raw.length||r.sourceObservedAt?.from!==times[0]||r.sourceObservedAt?.to!==times.at(-1))throw Error('Invalid cloud source population');const projected=raw.map(x=>projectDelivery(x,day)).sort((a,b)=>a.id.localeCompare(b.id));if(sha(projected)!==sha(s.rows))throw Error('Cloud source projection mismatch');return Object.freeze({day,snapshotHash:s.snapshotHash,observedAt:s.deliveryObservedAt,rows:s.rows.length,pages:pages.length,[verified]:true});}
